	@Test
	void identicalCostingMetricBundlesShareOneAtomicReservation() {
		long initialBytes = PackedCostingTraceArena.requiredBytesForCapacity(
				16, 16, 16, 16, 16, PackedPrimitiveHash.tableCapacity(16));
		PackedSearchBudget budget = new PackedSearchBudget(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, initialBytes));
		PackedCostingTraceArena trace = new PackedCostingTraceArena(budget);
		PackedCostContext context = new PackedCostContext();
		PackedCostEstimate providerInput = new PackedCostEstimate();
		PackedCostEstimate output = new PackedCostEstimate();
		for (int ordinal = 0; ordinal < 16; ordinal++) {
			output.putPlannedStringMetric("shared-string-" + ordinal, "value-" + ordinal);
			output.putPlannedDoubleMetric("shared-double-" + ordinal, ordinal + 0.25d);
		}

		assertThat(trace.append(PackedCostingPhase.LEAF, 1, context, 0, context,
				providerInput, output, 1.0d)).isEqualTo(1);
		assertThat(trace.append(PackedCostingPhase.LEAF, 2, context, 0, context,
				providerInput, output, 1.0d))
						.as("an identical immutable metric bundle must not reserve the same cells twice")
						.isEqualTo(2);

		PackedCostingTrace snapshot = trace.snapshot();
		assertThat(snapshot.stringMetricCount(1)).isEqualTo(16);
		assertThat(snapshot.stringMetricCount(2)).isEqualTo(16);
		assertThat(snapshot.stringMetricName(2, 15)).isEqualTo("shared-string-15");
		assertThat(snapshot.stringMetricValue(2, 15)).isEqualTo("value-15");
		assertThat(snapshot.doubleMetricCount(2)).isEqualTo(16);
		assertThat(snapshot.doubleMetricName(2, 15)).isEqualTo("shared-double-15");
		assertThat(snapshot.doubleMetricValue(2, 15)).isEqualTo(15.25d);
		PackedCostingTrace.Projection projection = trace.project(new int[] { 2 });
		int projectedEventId = projection.eventId(2);
		assertThat(projection.trace().stringMetricName(projectedEventId, 15)).isEqualTo("shared-string-15");
		assertThat(projection.trace().doubleMetricValue(projectedEventId, 15)).isEqualTo(15.25d);
		assertThat(budget.retainedBytes()).isEqualTo(initialBytes);
		assertThat(budget.completionStatus()).isEqualTo(PackedSearchCompletionStatus.EXACT_COMPLETE);
	}

