	@Test
	void sequentialPhysicalMetadataArenasReuseClearedStorage() {
		var threadMemory = ManagementFactory.getThreadMXBean();
		assumeTrue(threadMemory instanceof com.sun.management.ThreadMXBean,
				"thread allocation accounting is unavailable on this JVM");
		com.sun.management.ThreadMXBean allocations = (com.sun.management.ThreadMXBean) threadMemory;
		assumeTrue(allocations.isThreadAllocatedMemorySupported(),
				"thread allocation accounting is unavailable on this JVM");
		if (!allocations.isThreadAllocatedMemoryEnabled()) {
			allocations.setThreadAllocatedMemoryEnabled(true);
		}
		PackedPhysicalMetadataArena blocker = borrowPhysicalMetadata(0);
		try {
			PhysicalMetadataAllocation first = physicalMetadataAllocation(allocations, 4_096, 10.0d, "first", 1L);
			PhysicalMetadataAllocation second = physicalMetadataAllocation(allocations, 4_096, 20.0d, "second", 2L);

			assertThat(first.lastId()).isEqualTo(4_096);
			assertThat(second.lastId()).isEqualTo(4_096);
			assertThat(second.lastRows()).isEqualTo(4_116.0d);
			assertThat(second.lastRandomSeeks()).isEqualTo(1.0d);
			assertThat(second.lastMetric()).isEqualTo("second");
			assertThat(second.lastRuleProofMask())
					.as("recycled rows must not retain rule proofs from an earlier query")
					.isEqualTo(2L);
			assertThat(second.allocatedBytes() * 2L)
					.as("the recycled arena should avoid reallocating its wide primitive columns")
					.isLessThan(first.allocatedBytes());
		} finally {
			recyclePhysicalMetadata(blocker);
		}
	}

