	@Test
	void planQualityAuditAcceptsExplicitRetainedByteLimit() {
		Method auditPlanQuality;
		try {
			auditPlanQuality = PackedCascadesPlanner.class.getMethod("auditPlanQuality", TupleExpr.class,
					org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal.class,
					PackedCostModel.class, PackedPredicateRangeProvider.class, int.class, PackedPlannerLimits.class);
		} catch (NoSuchMethodException e) {
			throw new AssertionError(
					"plan-quality audits must accept the same explicit retained-byte limit as planning",
					e);
		}
		TupleExpr source = chain(4);
		PackedCostModel costModel = (query, relationId) -> 1.0d;
		var exactGoal = org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal.root();

		PackedPlanQualityAuditResult limited = (PackedPlanQualityAuditResult) invoke(PackedCascadesPlanner.class, null,
				auditPlanQuality, source, exactGoal, costModel, null, 2,
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, 64L * 1024L));
		PackedPlanQualityAuditResult complete = (PackedPlanQualityAuditResult) invoke(PackedCascadesPlanner.class, null,
				auditPlanQuality, source.clone(), exactGoal, costModel, null, 2, PackedPlannerLimits.unbounded());

		assertThat(limited.selectedPlanningResult().completionStatus())
				.isEqualTo(PackedSearchCompletionStatus.INCOMPLETE_RESOURCE_LIMIT);
		assertThat(limited.selectedPlanningResult().retainedBytes()).isLessThanOrEqualTo(64L * 1024L);
		assertThat(limited.alternatives()).anyMatch(PackedPlanQualityAlternative::selectedByPolicy);
		assertThat(complete.selectedPlanningResult().completionStatus())
				.isEqualTo(PackedSearchCompletionStatus.EXACT_COMPLETE);
		assertThat(complete.rootCandidateCount()).isGreaterThanOrEqualTo(limited.rootCandidateCount());
	}

	@Test
	void resourceLimitedWinnerSkipsDependentPlanWithoutImmutableMetadata() {
		PackedQuery query = PackedQueryCodec.encode(chain(2));
		PackedSearchBudget budget = new PackedSearchBudget(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, 0L));
		PackedMemo memo = new PackedMemo(query, 130, 4, 4, 4, 4, 8, budget);
		int rootGroupId = memo.logicalGroupId(query.rootRelId());
		int anyPropertyId = memo.anyPropertyId();
		int[] noChildren = new int[0];
		int physical = memo.addPhysicalAlternative(rootGroupId, PackedRelOp.JOIN, 0, anyPropertyId, 7,
				noChildren, 0, 0);
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(1.0d, 1.0d);

		int metadataId = memo.addPhysicalMetadata(estimate, 1.0d, 1.0d);
		int winnerId = memo.offerWinnerWithMetadata(rootGroupId, anyPropertyId, 0, 0, 0, physical,
				metadataId, 0.0d, 1.0d, 1.0d, noChildren, 0, 0);

		assertThat(metadataId).as("the retained-byte limit rejects the immutable metadata row").isZero();
		assertThat(winnerId).as("resource exhaustion still preserves an executable incumbent").isPositive();
		assertDoesNotThrow(() -> memo.putDependentPlan(winnerId, 1, winnerId));
		assertThat(memo.dependentPlanWinnerId(winnerId, 1))
				.as("a mutable winner slot must not masquerade as an immutable dependent-plan key")
				.isZero();
	}

	@Test
	void resourceLimitedParentAcceptsExecutableFallbackChildWithoutMetadata() {
		PackedQuery query = PackedQueryCodec.encode(chain(2));
		PackedSearchBudget budget = new PackedSearchBudget(
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, 0L));
		PackedMemo memo = new PackedMemo(query, 130, 4, 4, 4, 4, 8, budget);
		int rootRelationId = query.rootRelId();
		int rootGroupId = memo.logicalGroupId(rootRelationId);
		int childGroupId = memo.logicalGroupId(query.relChild(rootRelationId, 0));
		int anyPropertyId = memo.anyPropertyId();
		int[] noChildren = new int[0];
		int childPhysical = memo.addPhysicalAlternative(childGroupId, PackedRelOp.STATEMENT_PATTERN, 0,
				anyPropertyId, 1, noChildren, 0, 0);
		int childWinnerId = memo.offerExecutableFallbackWinnerWithMetadata(childGroupId, anyPropertyId, 0, 0, 0,
				childPhysical, 0, 0, 0.0d, 1.0d, 1.0d, noChildren, 0, 0);
		int[] childWinners = { childWinnerId };
		int[] childGroups = { childGroupId };
		int parentPhysical = memo.addPhysicalAlternative(rootGroupId, PackedRelOp.FILTER, 0, anyPropertyId, 7,
				childGroups, 0, 1);

		int parentWinnerId = assertDoesNotThrow(() -> memo.offerWinnerWithMetadata(rootGroupId, anyPropertyId,
				0, 0, 0, parentPhysical, 0, 0.0d, 2.0d, 2.0d, childWinners, 0, 1));

		assertThat(childWinnerId).isPositive();
		assertThat(parentWinnerId)
				.as("fallback propagation must preserve a metadata-less executable parent after resource exhaustion")
				.isPositive();
	}

